func TestGetQuantity_ReturnsCorrectAmount(t *testing.T) {
    cart := NewCart()
    cart.AddItem("SKU-001", "Widget", 1000, 5)
    if cart.GetQuantity("SKU-001") != 5 {
        t.Errorf("expected quantity 5, got %d", cart.GetQuantity("SKU-001"))
