func TestGetQuantity_NonExistent_ReturnsZero(t *testing.T) {
    cart := NewCart()
    if cart.GetQuantity("SKU-999") != 0 {
        t.Errorf("expected quantity 0 for non-existent, got %d", cart.GetQuantity("SKU-999"))
    }
}
