```go
cat > /Users/keithavery/Projects/thunderdome/results/benchmarks/tdd-shopping-cart/andy-dwyer/shopping_cart.go << 'EOF'
package cart

type DiscountType int

const (
	DiscountPercent DiscountType = iota
	DiscountFixed
)

type CartItem struct {
	SKU      string
	Name     string
	Price    int64
	Quantity int
}

type discount struct {
	code         string
	discountType DiscountType
	value        int64
}

type Cart struct {
	items    map[string]*CartItem
	discount *discount
}

func NewCart() *Cart {
	return &Cart{
		items: make(map[string]*CartItem),
	}
}

func (c *Cart) AddItem(sku, name string, price int64, quantity int) {
	if existing, ok := c.items[sku]; ok {
		existing.Quantity += quantity
	} else {
		c.items[sku] = &CartItem{
			SKU:      sku,
			Name:     name,
			Price:    price,
			Quantity: quantity,
		}
	}
}

func (c *Cart) RemoveItem(sku string, quantity int) {
	if item, ok := c.items[sku]; ok {
		item.Quantity -= quantity
		if item.Quantity <= 0 {
			delete(c.items, sku)
		}
	}
}

func (c *Cart) Clear() {
	c.items = make(map[string]*CartItem)
}

func (c *Cart) ItemCount() int {
	count := 0
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

func (c *Cart) GetItems() []CartItem {
	result := make([]CartItem, 0, len(c.items))
	for _, item := range c.items {
		result = append(result, *item)
	}
	return result
}

func (c *Cart) HasItem(sku string) bool {
	_, ok := c.items[sku]
	return ok
}

func (c *Cart) GetQuantity(sku string) int {
	if item, ok := c.items[sku]; ok {
		return item.Quantity
	}
	return 0
}

func (c *Cart) Subtotal() int64 {
	var total int64
	for _, item := range c.items {
		total += item.Price * int64(item.Quantity)
	}
	return total
}

func (c *Cart) Total() int64 {
	subtotal := c.Subtotal()
	if c.discount == nil {
		return subtotal
	}

	var discountAmount int64
	if c.discount.discountType == DiscountPercent {
		discountAmount = subtotal * c.discount.value / 100
	} else {
		discountAmount = c.discount.value
	}

	result := subtotal - discountAmount
	if result < 0 {
		return 0
	}
	return result
}

func (c *Cart) ApplyDiscount(code string, discountType DiscountType, value int64) {
	c.discount = &discount{
		code:         code,
		discountType: discountType,
		value:        value,
	}
}

func (c *Cart) RemoveDiscount() {
	c.discount = nil
}

func (c *Cart) DiscountAmount() int64 {
	if c.discount == nil {
		return 0
	}
	subtotal := c.Subtotal()
	var discountAmount int64
	if c.discount.discountType == DiscountPercent {
		discountAmount = subtotal * c.discount.value / 100
	} else {
		discountAmount = c.discount.value
	}
	if discountAmount > subtotal {
		return subtotal
	}
	return discountAmount
}
EOF
